      printf 'PRODUCTION_PROCESS_SIGNAL_SENT=false\n'
      printf 'WRITER_STOP_PERFORMED=false\n'
      printf 'GUI_STOPPED_OR_RESTARTED=false\n'
      printf 'SUDOERS_CHANGED=false\n'
      printf 'PRODUCTION_DB_SQL_CONNECTION_USED=false\n'
      printf 'PRODUCTION_BACKUP_CREATED=false\n'
      printf 'FINAL_APPROVAL_TOKEN_CREATED=false\n'
      printf 'APPROVAL_BINDING_CREATED=false\n'
