"$PYTHON_BIN" - "$CANDIDATE_ROOT" <<'PY'
from __future__ import annotations
import base64
import io
import os
import sys
import zipfile
from pathlib import Path

root = Path(sys.argv[1]).resolve()
payload = """"""
data = base64.b64decode(payload, validate=True)

expected = {
    "3e_j_operation_manual.md",
    "candidate-manifest.json",
    "one_shot_writer_freeze_backup_restart_runner.py",
    "root_fd_metadata_helper.py",
    "runner-policy.json",
    "test_3e_j_runner_negative.py",
    "validate_3e_j_runner_packet.py",
}

with zipfile.ZipFile(io.BytesIO(data), "r") as archive:
    names = set(archive.namelist())
    assert names == expected
    for member in archive.infolist():
        assert not member.is_dir()
        assert "/" not in member.filename
        target = root / member.filename
        descriptor = os.open(
            target,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
            0o640,
        )
        with os.fdopen(descriptor, "wb", closefd=True) as stream:
            stream.write(archive.read(member))
            stream.flush()
            os.fsync(stream.fileno())

print("CORRECTED_CANDIDATE_PAYLOAD_DECODE=PASS")
print(f"CORRECTED_CANDIDATE_FILE_COUNT={len(expected)}")
PY

