for artifact in sorted(
    evidence_root.rglob("*"),
    key=lambda path: path.relative_to(evidence_root).as_posix(),
):
    if artifact.is_file() and artifact != manifest_path:
        manifest_lines.append(
            f"{sha256(artifact)}  "
            f"{artifact.relative_to(evidence_root).as_posix()}"
        )
manifest_path.write_text("\n".join(manifest_lines) + "\n", encoding="utf-8")

for line in manifest_path.read_text(encoding="utf-8").splitlines():
    expected, relative = line.split("  ", 1)
    artifact = evidence_root / relative
    assert artifact.is_file()
    assert sha256(artifact) == expected

repo_stat = repo_root.stat()
files = [path for path in evidence_root.rglob("*") if path.is_file()]
directories = sorted(
    [path for path in evidence_root.rglob("*") if path.is_dir()],
    key=lambda path: len(path.relative_to(evidence_root).parts),
    reverse=True,
)
for artifact in [*files, *directories, evidence_root]:
    metadata = artifact.lstat()
    assert not stat.S_ISLNK(metadata.st_mode)
    assert metadata.st_uid == repo_stat.st_uid
    assert metadata.st_gid == repo_stat.st_gid

for artifact in files:
    os.chmod(artifact, 0o444)
for directory in directories:
    os.chmod(directory, 0o555)
